#pragma once

#include <cstddef>
#include <string_view>

namespace upscaler {

enum class Model
{
    Live,
    Anime
};

inline const char* modeName(Model model)
{
    return model == Model::Live ? "live" : "anime";
}

struct Resource
{
    const unsigned char* data;
    size_t size;
};

// Generated by CMake. Every model and SPIR-V module resides in the executable.
Resource embeddedResource(std::string_view name);

} // namespace upscaler
